div.script:
document.addEventListener("DOMContentLoaded", function() {
    var timerDisplay = document.getElementById('timer_display');
    var countdownBox = document.getElementById('countdown_box');
    var duration = 15 * 60; // 15 minutes en secondes
    var timer = duration, minutes, seconds;

    var interval = setInterval(function () {
        minutes = parseInt(timer / 60, 10);
        seconds = parseInt(timer % 60, 10);

        minutes = minutes < 10 ? "0" + minutes : minutes;
        seconds = seconds < 10 ? "0" + seconds : seconds;

        if (timerDisplay) {
            timerDisplay.textContent = minutes + ":" + seconds;
        }

        if (--timer < 0) {
            clearInterval(interval);
            if (countdownBox) {
                countdownBox.classList.remove('alert-warning');
                countdownBox.classList.add('alert-danger');
                countdownBox.innerHTML = "<strong>Délai expiré.</strong> Le lien n'est plus valide, veuillez recommencer votre inscription.";
            }
        }
    }, 1000);
});
